with affected as(select distinct t.id from threads t join mobile_recipient_threads map on map.thread_id=t.id where map.recipient_type='parent_athlete'and coalesce(t.is_group,false)=false and(t.organization_id is not null or t.org_id is not null))update messages m set workspace_id=null where m.thread_id in(select id from affected);
with affected as(select distinct t.id from threads t join mobile_recipient_threads map on map.thread_id=t.id where map.recipient_type='parent_athlete'and coalesce(t.is_group,false)=false)update threads t set org_id=null,organization_id=null,organization_display_name=null,organization_profile_image_url=null,title='Family conversation',updated_at=now()where t.id in(select id from affected);
create or replace function public.reconcile_message_thread_organization_identity()returns trigger language plpgsql security definer set search_path=public as $$ declare v_org uuid;begin if exists(select 1 from mobile_recipient_threads map where map.thread_id=new.thread_id and map.recipient_type='parent_athlete')then return new;end if;if new.workspace_id is null then return new;end if;select organization_id into v_org from business_workspaces where id=new.workspace_id and workspace_type='organization';if v_org is not null then update threads t set org_id=coalesce(t.org_id,v_org),organization_id=coalesce(t.organization_id,v_org),organization_display_name=coalesce(t.organization_display_name,o.name),organization_profile_image_url=coalesce(t.organization_profile_image_url,s.profile_image_url)from organizations o left join org_settings s on s.org_id=o.id where t.id=new.thread_id and o.id=v_org;end if;return new;end $$;
notify pgrst,'reload schema';
